async function init(){controls();const text=await fetch('data/macaque_tsne_workflow_cells.csv?v=macaque-e4-workflow-20260922').then(r=>{if(!r.ok)throw Error(r.status);return r.text()});rows=parseCsv(text).map(r=>({...r,x:+r.tSNE_1,y:+r.tSNE_2,consensus:/true/i.test(r.HC_GC_consensus),T_identity:r.T_identity,strictT:/true/i.test(r.strict_T_stable)}));if(rows.length!==390)throw Error(`Expected 390 cells, found ${rows.length}`);sync();render()}
init().catch(e=>$('tsneStatus').textContent='Unable to load Macaque t-SNE data: '+e.message);
